INSERT INTO species_profile (species_id, nongsaro_no, name, scientific_name, genus, english_name, distribution_name, family_name, category_names, leaf_color_names, difficulty, light_names, light_min, light_max, placement_names, growth_temp_name, growth_temp_min, growth_temp_max, winter_min_temp, humidity_name, water_spring, water_summer, water_autumn, water_winter, features, special_care, advice, pests, toxicity)
VALUES
  (1, '12938', '가울테리아', 'Gaultheria procumbens', 'Gaultheria', 'Checkerberry, Eastern Teaberry, (Spreading) Wintergreen', '파스향나무 (추천 유통명: 가울테리아)', '진달래과', '잎&꽃보기식물,열매보기식물', '녹색, 연두색', 'NORMAL', '중간 광도(800~1,500 Lux),높은 광도(1,500~10,000 Lux)', 'MEDIUM', 'HIGH', '거실 창측 (실내깊이 150~300cm),발코니 내측 (실내깊이 50~150cm),발코니 창측 (실내깊이 0~50cm)', '16~20℃', 16, 20, 0, '40 ~ 70%', '토양 표면이 말랐을때 충분히 관수함', '토양 표면이 말랐을때 충분히 관수함', '토양 표면이 말랐을때 충분히 관수함', '화분 흙 대부분 말랐을때 충분히 관수함', '진달래과의 작은 관목으로 척박한 산성토양에서 잘 자라며 키는 20cm정도로 포복형이다. 암석정원에 잘 어울린다.', NULL, '식용, 지피, 약용, 향기,관엽, 관화, 관실', NULL, NULL),
  (2, '12954', '개운죽', 'Dracaena sanderiana ''Virens''', 'Dracaena', 'Sander''s dracaena', '개운죽', '백합과', '잎보기식물', '녹색, 연두색', 'EASY', '낮은 광도(300~800 Lux),중간 광도(800~1,500 Lux),높은 광도(1,500~10,000 Lux)', 'LOW', 'HIGH', '거실 내측 (실내깊이 300~500cm),거실 창측 (실내깊이 150~300cm),발코니 내측 (실내깊이 50~150cm),발코니 창측 (실내깊이 0~50cm)', '16~20℃', 16, 20, 13, '40 ~ 70%', '흙을 촉촉하게 유지함(물에 잠기지 않도록 주의)', '흙을 촉촉하게 유지함(물에 잠기지 않도록 주의)', '흙을 촉촉하게 유지함(물에 잠기지 않도록 주의)', '토양 표면이 말랐을때 충분히 관수함', '화분에 심을 경우에는 부드럽고 배수가 잘 되는 토양에 심음 ※ 개운죽은 관엽으로 분류되어 있지만 사실은 잎보다 잎이 떨어진 후 대나무처럼 보이는 줄기가 더욱 관상의 대상이 된다. 직선보다 곡선의 줄기가 필요한 경우에는 줄기를 곡선으로 유도할 수 있다.', '수경은 물주기가 필요 없으나, 화분은 1-2주에 한번씩 충분히 관수한다.', '대나무를 닮아서 이름까지 얻게 되었지만 사실은 대나무가 아닌 드라세나속의 관엽', NULL, '있음'),
  (3, '12955', '골드크레스트 ''윌마''', 'Cupressus macrocarpa ''Wilma''', 'Cupressus', 'Monterey cypress', '율마, 골드크리스터 (추천 유통명: 윌마)', '측백나무과', '잎보기식물', '녹색, 연두색', 'NORMAL', '높은 광도(1,500~10,000 Lux)', 'HIGH', 'HIGH', '거실 창측 (실내깊이 150~300cm),발코니 내측 (실내깊이 50~150cm),발코니 창측 (실내깊이 0~50cm)', '16~20℃', 16, 20, 10, '40 ~ 70%', '토양 표면이 말랐을때 충분히 관수함', '토양 표면이 말랐을때 충분히 관수함', '토양 표면이 말랐을때 충분히 관수함', '화분 흙 대부분 말랐을때 충분히 관수함', '※ Cupressus macrocarpa 품종 중에 ''wilma'', ''goldcrest'' 등의 품종이 있는데, 우리가 사용하고 있는 율마라는 이름은 “wilma"에서 나온 것으로 생각된다. 따라서 율마라는 이름이 윌마로 교정되어야하지 않을까 고려된다.바람에 약하며 줄기 아랫부분의 잎이 떨어지면 황량한 느낌을 주지만 토피아리 형식으로 키울 수도 있다.크리스마스 트리로 실내에 장식하면 좋다.', '겨울에는 건조하게 관리한다. 어린 나무일수록 물을 더 자주 준다.', '부드러운 연두빛의 침엽수를 연상하게 하는 실내식물로 허브 향을 지님', NULL, NULL),
  (4, '12957', '공작야자', 'Caryota mitis', 'Caryota', 'Fish tail palm, Burmese Fishtail Palm, Clustered Fishtail Palm', '공작야자, (추천 유통명: 미티스야자)', '야자과', '잎보기식물', '녹색, 연두색', 'NORMAL', '중간 광도(800~1,500 Lux),높은 광도(1,500~10,000 Lux)', 'MEDIUM', 'HIGH', '거실 창측 (실내깊이 150~300cm),발코니 내측 (실내깊이 50~150cm),발코니 창측 (실내깊이 0~50cm)', '21~25℃', 21, 25, 13, '70% 이상', '토양 표면이 말랐을때 충분히 관수함', '토양 표면이 말랐을때 충분히 관수함', '토양 표면이 말랐을때 충분히 관수함', '토양 표면이 말랐을때 충분히 관수함', '포름알데히드, 벤젠, 톨루엔, 트리클로로 에틸렌', NULL, '방풍 / 차폐 / 가장자리 경계', NULL, NULL),
  (5, '12962', '관엽베고니아', 'Begonia spp.', 'Begonia', 'foliage begonia', NULL, '베고니아과', '잎&꽃보기식물', '녹색, 연두색,은색, 회색,빨강, 분홍, 자주색', 'NORMAL', '중간 광도(800~1,500 Lux),높은 광도(1,500~10,000 Lux)', 'MEDIUM', 'HIGH', '거실 창측 (실내깊이 150~300cm),발코니 내측 (실내깊이 50~150cm),발코니 창측 (실내깊이 0~50cm)', '16~20℃', 16, 20, 13, '40 ~ 70%', '토양 표면이 말랐을때 충분히 관수함', '토양 표면이 말랐을때 충분히 관수함', '토양 표면이 말랐을때 충분히 관수함', '토양 표면이 말랐을때 충분히 관수함', NULL, NULL, NULL, NULL, NULL),
  (6, '12963', '관음죽', 'Rhapis excelsa', 'Rhapis', 'Fan Palms, (Large) Lady Palm, Bamboo Palm, Broad-leaved Lady Palm, Ground Rattan', '관음죽', '야자과', '잎보기식물', '녹색, 연두색', 'NORMAL', '낮은 광도(300~800 Lux),중간 광도(800~1,500 Lux),높은 광도(1,500~10,000 Lux)', 'LOW', 'HIGH', '실내 어두운 곳 (실내깊이 500 이상cm),거실 내측 (실내깊이 300~500cm),거실 창측 (실내깊이 150~300cm),발코니 내측 (실내깊이 50~150cm),발코니 창측 (실내깊이 0~50cm)', '16~20℃', 16, 20, 5, '40 ~ 70%', '토양 표면이 말랐을때 충분히 관수함', '토양 표면이 말랐을때 충분히 관수함', '토양 표면이 말랐을때 충분히 관수함', '화분 흙 대부분 말랐을때 충분히 관수함', '손바닥 모양의 잎을 가진 집에서 기르기 쉽고 그늘과 추위에도 잘 견디고 병해충에도 강하기기 때문에 기르기 쉬운 식물이다. 자라는 속도가 느려서 관리가 편하다. 반엽이 들어있는 종은 색상이 더욱 아름답다. 2년에 한 번씩 분갈이를 해 주면 좋다.', '관음죽을 지하관수나 수경재배로 기르는 경우에는 수돗물 속의 염분이나 미네랄이 잎 끝에 축적되어 갈색으로 변할 수도 있다. 이런 현상이 나타날 때에는 갈색으로 변한 부분만 가위로 잘라내면 된다. 그러면 염분도 제거할 수 있고 특유의 톱니모양의 녹색 잎을 유지시킬 수 있다.', '컨테이너, 경계, 차폐, 방풍/ 암모니아 흡수에 최강인 관엽식물', '일반적으로 병이나 해충이 없으나 매우 드물게 응애가 생기기도 한다.', '수액이 인체의 피부나 점막을 자극할 수 있음'),
  (7, '12966', '구문초', 'Pelargonium rosium', 'Pelargonium', 'rose geranium', '모기풀, (추천 유통명: 구문초)', '쥐손이풀과', '잎&꽃보기식물', '녹색, 연두색', NULL, '중간 광도(800~1,500 Lux),높은 광도(1,500~10,000 Lux)', 'MEDIUM', 'HIGH', '거실 창측 (실내깊이 150~300cm),발코니 내측 (실내깊이 50~150cm),발코니 창측 (실내깊이 0~50cm)', '16~20℃', 16, 20, 10, '40 ~ 70%', '토양 표면이 말랐을때 충분히 관수함', '토양 표면이 말랐을때 충분히 관수함', '토양 표면이 말랐을때 충분히 관수함', '화분 흙 대부분 말랐을때 충분히 관수함', NULL, NULL, NULL, NULL, '모기퇴치 식물'),
  (8, '12972', '구즈마니아', 'Guzmania lingulata', 'Guzmania', 'Striped torch', '구즈마리아, (추천 유통명: 구즈마니아)', '파인애플과', '잎&꽃보기식물', '녹색, 연두색,흰색, 크림색', 'NORMAL', '중간 광도(800~1,500 Lux),높은 광도(1,500~10,000 Lux)', 'MEDIUM', 'HIGH', '거실 창측 (실내깊이 150~300cm),발코니 내측 (실내깊이 50~150cm),발코니 창측 (실내깊이 0~50cm)', '21~25℃', 21, 25, 13, '40 ~ 70%', '토양 표면이 말랐을때 충분히 관수함', '토양 표면이 말랐을때 충분히 관수함', '토양 표면이 말랐을때 충분히 관수함', '토양 표면이 말랐을때 충분히 관수함', '식물체 중심 잎과 잎 포기 사이 물통에 물이 고이도록 함', '이 구즈마니아는 습도가 높은 것을 좋아하며, 음지에서 잘 자라기 때문에 아파트에서 기를 경우 차광을 강하게 하는 것이 바람직하다. 생육에 알맞은 온도는 낮에는 25-30℃, 밤에는 20℃ 정도이며 추위에는 약한 편으로 겨울에 10℃ 이상은 유지해 주어야 안전하게 월동할 수 있다.', '꽃말 ''만족''', NULL, NULL),
  (9, '12974', '군자란', 'Clivia miniata', 'Clivia', 'Scarlet Caffir Lily,Kaffir Lily, Clivia, Bush lily', NULL, '수선화과', '잎&꽃보기식물', '녹색, 연두색,흰색, 크림색', 'NORMAL', '중간 광도(800~1,500 Lux),높은 광도(1,500~10,000 Lux)', 'MEDIUM', 'HIGH', '거실 창측 (실내깊이 150~300cm),발코니 내측 (실내깊이 50~150cm),발코니 창측 (실내깊이 0~50cm)', '16~20℃', 16, 20, 10, '40 ~ 70%', '토양 표면이 말랐을때 충분히 관수함', '토양 표면이 말랐을때 충분히 관수함', '토양 표면이 말랐을때 충분히 관수함', '화분 흙 대부분 말랐을때 충분히 관수함', NULL, '군자란의 수명은 30년 이상으로 장수하는 식물이다. 어린 묘로부터 시작하면 3년은 지나야 꽃이 피지만, 일단 꽃을 피운 것은 이듬해부터는 매년 꽃을 피운다. 씨앗으로 번식해도 되지만 꽃이 피기까지 5년 정도 걸리기 때문에 보통은 포기나누기 한다. 씨앗은 11월경에 충분히 성숙된 것을 따서 뿌리면 되는데 다소 저온인 16-21℃에서 발아가 잘된다. 포기나누기는 늦은 겨울이나 이른 봄에 한다.', '꽃말: 고귀, / 君子蘭(군자란)은 이름 끝에 ‘란’이라고 되어있지만 난 종류가 아님/컨테이너, 표본, 경계', NULL, '복용시 치명적 독성'),
  (10, '12988', '글레코마', 'Glecoma hederacea ''Variegata''', 'Glecoma', 'Ground ivy, Gill-over-the-ground', NULL, '꿀풀과', '잎&꽃보기식물', '녹색, 연두색,흰색, 크림색', 'EASY', '중간 광도(800~1,500 Lux),높은 광도(1,500~10,000 Lux)', 'MEDIUM', 'HIGH', '거실 창측 (실내깊이 150~300cm),발코니 내측 (실내깊이 50~150cm),발코니 창측 (실내깊이 0~50cm)', '16~20℃', 16, 20, 5, '40 ~ 70%', '토양 표면이 말랐을때 충분히 관수함', '토양 표면이 말랐을때 충분히 관수함', '토양 표면이 말랐을때 충분히 관수함', '화분 흙 대부분 말랐을때 충분히 관수함', NULL, NULL, NULL, NULL, NULL),
  (11, '12990', '금목서', 'Osmanthus fragrans', 'Osmanthus', 'sweet Osmanthus, tea Osmanthus, sweet Olive', '목서, 금목서, 구골나무, 박달목서, (추천 유통명 : 금목서)', '물푸레나무과', '잎&꽃보기식물', '녹색, 연두색', 'EASY', '중간 광도(800~1,500 Lux),높은 광도(1,500~10,000 Lux)', 'MEDIUM', 'HIGH', '거실 창측 (실내깊이 150~300cm),발코니 내측 (실내깊이 50~150cm),발코니 창측 (실내깊이 0~50cm)', '16~20℃', 16, 20, 0, '40 ~ 70%', '토양 표면이 말랐을때 충분히 관수함', '토양 표면이 말랐을때 충분히 관수함', '토양 표면이 말랐을때 충분히 관수함', '토양 표면이 말랐을때 충분히 관수함', '땅에서부터 많은 줄기가 올라와 생울타리로 적당하다.', '- 실내환경: 밝고 시원한 곳 - 전지전정: 무성한 성장을 촉진시키기 위해 정기적으로 적심함', '꽃말:유혹 / 컨테이너, 분재, 토피아리, 생울타리, 차폐식재, 실내식물 / 속명 Osmanthus를 풀어보면 osme는 냄새나 향기를 뜻하고, anthos는 꽃을 의미함', '개각충 등 (깨끗한 용기에 심기, 가정과 온실 도입시 유의 제거)', NULL),
